from fractions import Fraction as F

def eta(a,b):
 if b<a:return 1-b/a
 if b>a:return 1-(1-b)/(1-a)
 return F(0)

def binary_dcp(probs,weights):
 candidates=set([F(0),F(1),*probs])
 return min((sum(w*eta(q,p) for p,w in zip(probs,weights)),q) for q in candidates)
print('Equal groups:',binary_dcp([F(49,100),F(51,100)],[F(1,2),F(1,2)]))
print('Minority group:',binary_dcp([F(0),F(1,100)],[F(1,100),F(99,100)]))
def surrogate(a,b):
 if b<a:return a*a-a*b
 if b>a:return (1-a)**2-(1-b)*(1-a)
 return F(0)
x=(F(1,2),F(1,4))
y=(F(3,5),F(11,20))
z=tuple((a+b)/2 for a,b in zip(x,y))
print('Eq.18 convexity witness:',{'x':str(surrogate(*x)),'y':str(surrogate(*y)),'midpoint':str(surrogate(*z)),'average':str((surrogate(*x)+surrogate(*y))/2)})
